import json

def merge_settings(defaults_json, user_json):
    defaults = json.loads(defaults_json)
    user = json.loads(user_json)
    merged = {**defaults, **user}
    merged["colors"] = {**defaults.get("colors", {}), **user.get("colors", {})}
    return merged

