from datetime import datetime, timedelta, timezone

def parse_time(text):
    if text.endswith("Z"):
        text = text[:-1] + "+00:00"
    return datetime.fromisoformat(text)

def per_day(texts):
    counts = {}
    for text in texts:
        day = parse_time(text).astimezone(timezone.utc).date().isoformat()
        counts[day] = counts.get(day, 0) + 1
    return dict(sorted(counts.items()))

