from datetime import datetime, timedelta, timezone

def parse_time(text):
    if text.endswith("Z"):
        text = text[:-1] + "+00:00"
    return datetime.fromisoformat(text)

def show_local(text, hours):
    local = parse_time(text).astimezone(timezone(timedelta(hours=hours)))
    return local.strftime("%d/%m/%Y %H:%M") + f" (UTC{hours:+d})"

