import csv
import json

def load_ratings(path):
    ratings = []
    problems = []
    with open(path, newline="", encoding="utf-8") as f:
        for line, row in enumerate(csv.DictReader(f), start=2):
            try:
                stars = int(row["stars"])
            except ValueError:
                problems.append(f"line {line}: bad stars {row['stars']!r}")
                continue
            if not 1 <= stars <= 5:
                problems.append(f"line {line}: stars out of range {stars}")
                continue
            ratings.append({"movie": row["movie"], "user": row["user"], "stars": stars})
    return ratings, problems

def averages(ratings):
    totals = {}
    for r in ratings:
        totals.setdefault(r["movie"], []).append(r["stars"])
    return {movie: round(sum(s) / len(s), 1) for movie, s in totals.items()}

def top_movies(avgs, n=3):
    ranked = sorted(avgs.items(), key=lambda item: (-item[1], item[0]))
    return [movie for movie, avg in ranked[:n]]

def stars_text(avg):
    full = int(avg + 0.5)   # round halves up
    return "★" * full + "☆" * (5 - full)


def summary(path):
    ratings, problems = load_ratings(path)
    avgs = averages(ratings)
    lines = [f"{len(ratings)} ratings of {len(avgs)} movies, {len(problems)} skipped"]
    for movie in top_movies(avgs, len(avgs)):
        lines.append(f"{movie:<8}{stars_text(avgs[movie])} {avgs[movie]}")
    return lines

