    def price_report(self):
        by_author = {}
        for book in self.all_books():
            by_author.setdefault(book["author"], []).append(book["price"])
        lines = []
        for author in sorted(by_author):
            prices = by_author[author]
            word = "book" if len(prices) == 1 else "books"
            lines.append(f"{author}: {len(prices)} {word}, average {sum(prices) / len(prices):.2f}")
        return lines

