import csv
import json
import re
import sqlite3
from datetime import date
from io import StringIO

def check_date(text):
    if not re.fullmatch(r"\d{4}-\d{2}-\d{2}", text):
        return False
    try:
        date.fromisoformat(text)
    except ValueError:
        return False
    return True


def clean_row(row):
    day = row["date"].strip()
    if not check_date(day):
        raise ValueError(f"bad date {day!r}")
    region = row["region"].strip().lower()
    if not region:
        raise ValueError("missing region")
    try:
        amount = float(row["amount"])
    except ValueError:
        raise ValueError(f"bad amount {row['amount']!r}")
    if amount <= 0:
        raise ValueError(f"bad amount {row['amount']!r}")
    return {"date": day, "region": region, "product": row["product"].strip(), "amount": round(amount, 2)}


def read_sales(text):
    rows = []
    errors = []
    for line, row in enumerate(csv.DictReader(StringIO(text)), start=2):
        try:
            rows.append(clean_row(row))
        except ValueError as e:
            errors.append(f"line {line}: {e}")
    return rows, errors


def load_db(rows):
    conn = sqlite3.connect(":memory:")
    conn.execute("CREATE TABLE sales (date TEXT, region TEXT, product TEXT, amount REAL)")
    conn.executemany(
        "INSERT INTO sales VALUES (:date, :region, :product, :amount)",
        rows,
    )
    return conn


def region_totals(conn):
    query = "SELECT region, ROUND(SUM(amount), 2) AS total FROM sales GROUP BY region ORDER BY total DESC, region"
    return conn.execute(query).fetchall()


def monthly_totals(conn):
    query = "SELECT substr(date, 1, 7) AS month, ROUND(SUM(amount), 2) FROM sales GROUP BY month ORDER BY month"
    return dict(conn.execute(query).fetchall())


def run_pipeline(text):
    rows, errors = read_sales(text)
    conn = load_db(rows)
    best = conn.execute(
        "SELECT product FROM sales GROUP BY product ORDER BY SUM(amount) DESC, product LIMIT 1"
    ).fetchone()
    report = {
        "rows": len(rows),
        "errors": errors,
        "regions": dict(region_totals(conn)),
        "months": monthly_totals(conn),
        "best_product": best[0] if best else None,
    }
    conn.close()
    return json.dumps(report, indent=2)
